theorem MeanClass.bilinear_wave {s : StripData D} {P : ℕ → D → ℝ}
    {α β : ℝ} {f : ℕ → D → E} {g : ℕ → D → F}
    (hf : MeanClass s α f) (hg : WaveClass s P β g)
    (hζ : ∀ x ∈ s.domain, s.zeta x ≤ 1) (L : E →L[ℝ] F →L[ℝ] G) :
    WaveClass s P (α + β) (fun n x => L (f n x) (g n x))
